import { registerSW } from 'virtual:pwa-register';
import { pwaController, type PwaController } from './store';

/** How often an open panel checks for a new version. */
const UPDATE_CHECK_MS = 60 * 60_000;

/**
 * Registers the service worker generated by vite-plugin-pwa (generateSW,
 * registerType "prompt"): a new version waits until the user accepts the
 * prompt, so an operator is never reloaded in the middle of a check-in.
 * Queued offline operations are in IndexedDB and survive the reload.
 * Imported only by main.tsx (the virtual module exists only in Vite builds).
 */
export function registerPwa(controller: PwaController = pwaController): void {
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;
  const updateSW = registerSW({
    immediate: true,
    onNeedRefresh: () => controller.setNeedRefresh(),
    onOfflineReady: () => controller.setOfflineReady(),
    onRegisteredSW: (_url, registration) => {
      if (!registration) return;
      setInterval(() => {
        if (navigator.onLine) void registration.update().catch(() => undefined);
      }, UPDATE_CHECK_MS);
    },
  });
  controller.bindUpdater(() => updateSW(true));
}
